import React, { useState, useEffect } from 'react';
import TarjetaJuego from './TarjetaJuego';
import '../styles/BibliotecaJuegos.css';

const BibliotecaJuegos = ({ juegos, onEdit, onDelete, onViewReviews, onAgregarNuevo }) => {
  const [filtros, setFiltros] = useState({
    busqueda: '',
    genero: '',
    plataforma: '',
    completados: null,
    wishlist: null,
  });

  const [juegosFiltrados, setJuegosFiltrados] = useState(juegos);

  useEffect(() => {
    let resultado = [...juegos];

    // Filtrar por búsqueda
    if (filtros.busqueda) {
      resultado = resultado.filter((j) =>
        j.titulo.toLowerCase().includes(filtros.busqueda.toLowerCase()) ||
        j.desarrollador.toLowerCase().includes(filtros.busqueda.toLowerCase())
      );
    }

    // Filtrar por género
    if (filtros.genero) {
      resultado = resultado.filter((j) => j.genero === filtros.genero);
    }

    // Filtrar por plataforma
    if (filtros.plataforma) {
      resultado = resultado.filter((j) => j.plataforma === filtros.plataforma);
    }

    // Filtrar por completados
    if (filtros.completados !== null) {
      resultado = resultado.filter((j) => j.completado === filtros.completados);
    }

    // Filtrar por wishlist
    if (filtros.wishlist !== null) {
      resultado = resultado.filter((j) => (j.wishlist === true) === (filtros.wishlist === true));
    }

    setJuegosFiltrados(resultado);
  }, [juegos, filtros]);

  const handleFiltroChange = (e) => {
    const { name, value } = e.target;
    setFiltros({
      ...filtros,
      [name]: value === '' ? (name === 'completados' ? null : '') : name === 'completados' ? value === 'true' : value,
    });
  };

  const generosUnicos = [...new Set(juegos.map((j) => j.genero))];
  const plataformasUnicas = [...new Set(juegos.map((j) => j.plataforma))];

  return (
    <div className="biblioteca-juegos">
      <div className="biblioteca-header">
        <div className="biblioteca-title">
          <h1>📚 Mi Biblioteca de Juegos</h1>
          <span className="total-juegos">{juegosFiltrados.length} juego{juegosFiltrados.length !== 1 ? 's' : ''}</span>
        </div>
        <button className="btn-agregar" onClick={onAgregarNuevo}>
          ➕ Agregar Juego
        </button>
      </div>

      <div className="filtros">
        <input
          type="text"
          name="busqueda"
          placeholder="🔍 Buscar juego o desarrollador..."
          value={filtros.busqueda}
          onChange={handleFiltroChange}
          className="filtro-busqueda"
        />

        <select
          name="genero"
          value={filtros.genero}
          onChange={handleFiltroChange}
          className="filtro-select"
        >
          <option value="">Todos los géneros</option>
          {generosUnicos.map((g) => (
            <option key={g} value={g}>
              {g}
            </option>
          ))}
        </select>

        <select
          name="plataforma"
          value={filtros.plataforma}
          onChange={handleFiltroChange}
          className="filtro-select"
        >
          <option value="">Todas las plataformas</option>
          {plataformasUnicas.map((p) => (
            <option key={p} value={p}>
              {p}
            </option>
          ))}
        </select>

        <select
          name="completados"
          value={filtros.completados === null ? '' : filtros.completados}
          onChange={handleFiltroChange}
          className="filtro-select"
        >
          <option value="">Todos los estados</option>
          <option value="true">Completados</option>
          <option value="false">Por completar</option>
        </select>
        <select
          name="wishlist"
          value={filtros.wishlist === null ? '' : filtros.wishlist}
          onChange={handleFiltroChange}
          className="filtro-select"
        >
          <option value="">Todos</option>
          <option value="true">Wishlist</option>
        </select>
      </div>

      {juegosFiltrados.length === 0 ? (
        <div className="sin-resultados">
          <p>No se encontraron juegos con los filtros aplicados 😔</p>
        </div>
      ) : (
        <div className="grilla-juegos">
          {juegosFiltrados.map((juego) => (
            <TarjetaJuego
              key={juego._id}
              juego={juego}
              onEdit={onEdit}
              onDelete={onDelete}
                onViewReviews={onViewReviews}
                onToggleWishlist={onToggleWishlist}
            />
          ))}
        </div>
      )}
    </div>
  );
};

export default BibliotecaJuegos;
